(122, 'mocaihuan',    'e10adc3949ba59abbe56e057f20f883e', '墨彩环',     'mocaihuan@fanren.dev',    '墨家三女，没有灵根。医道我照样学得下来。',               '/images/avatars/mocaihuan.svg',    'USER', 1),
